   496    template <typename Type>
   497    inline Type *allocate_size (unsigned int size)
   498    {
   499      if (unlikely (this->ran_out_of_room || this->end - this->head < ptrdiff_t (size))) {
   500        this->ran_out_of_room = true;
   501        return nullptr;
   502      }
   503      memset (this->head, 0, size);
   504      char *ret = this->head;
   505      this->head += size;
   506      return reinterpret_cast<Type *> (ret);
   507    }
